-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260529150000_td13_budgets_add_period.sql
-- ─────────────────────────────────────────────────────────────────────
-- TD-13 — server-side budget period columns.
--
-- Discovery during PR #20 prep: the previous SUPERSEDED README claimed
-- this had been applied to prod via the Dashboard, but the captured
-- baseline at 00000000000001_production_state_baseline.sql shows
-- budgets has neither `period` nor `period_start`/`period_end` columns.
-- So TD-13 was actually still on paper, like TD-08 and TD-09. This
-- migration re-lands it as a fresh additive change through the now-
-- validated `supabase db push` pipeline (PR #16 + hotfixes #17–#19).
--
-- Adds:
--   period       text not null default 'monthly'
--   period_start date null
--   period_end   date null
-- and a check constraint matching the consumer's BudgetPeriod enum.
--
-- Until this migration applies, the consumer falls back to per-device
-- localStorage overlays (`budgetMeta.ts`, per the v6.4 convention in
-- CLAUDE.md). After it applies, those overlays can fold into the cloud
-- write path in a follow-up PR.

begin;

alter table budgets
  add column if not exists period       text not null default 'monthly',
  add column if not exists period_start date null,
  add column if not exists period_end   date null;

-- Constraint name mirrors the previous superseded migration so anyone
-- diff-ing the two sees the equivalence.
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'budgets_period_check'
      and conrelid = 'public.budgets'::regclass
  ) then
    alter table budgets
      add constraint budgets_period_check
      check (period in ('monthly','quarterly','half_yearly','annual','custom'));
  end if;
end$$;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260529150500_td08_audit_triggers.sql
-- ─────────────────────────────────────────────────────────────────────
-- TD-08 — server-side audit triggers on the six domain tables.
--
-- Populates `activity_log` whenever a row in `transactions`, `budgets`,
-- `goals`, `debts`, `assets`, or `memberships` is inserted/updated/deleted.
-- The pre-PR-#16 design intent for this lived at
-- db/migrations-superseded/20260524071000_audit_triggers.sql but was
-- never applied to prod (per TD-20's honest residual). This migration
-- re-lands it through the validated auto-apply pipeline.
--
-- Two correctness details from the original review pass, preserved here:
--   (a) the trigger list includes `memberships` (multi-household member
--       changes are exactly the audit signal we need).
--   (b) the SECURITY DEFINER function pins `search_path = public, pg_temp`
--       so a hostile schema on the caller's search_path can't shadow
--       `activity_log` or `auth.uid()` and tamper with the audit trail.

begin;

create or replace function public.log_domain_activity()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  h       uuid;
  act     text;
  ent     text := tg_table_name;
  ent_id  uuid;
  ch      jsonb;
begin
  if tg_op = 'INSERT' then
    act    := 'created';
    h      := new.household_id;
    ent_id := new.id;
    ch     := to_jsonb(new);
  elsif tg_op = 'UPDATE' then
    act    := 'updated';
    h      := new.household_id;
    ent_id := new.id;
    ch     := jsonb_build_object('old', to_jsonb(old), 'new', to_jsonb(new));
  elsif tg_op = 'DELETE' then
    act    := 'deleted';
    h      := old.household_id;
    ent_id := old.id;
    ch     := to_jsonb(old);
  else
    return null;
  end if;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id, changes)
  values (h, auth.uid(), act, ent, ent_id, ch);

  return null;
end;
$$;

-- Trigger names are stable so future migrations can drop/recreate them
-- cleanly. `if not exists` would be ideal but Postgres doesn't support
-- it on CREATE TRIGGER (yet), so we wrap in a DO block.
do $$
begin
  if not exists (select 1 from pg_trigger where tgname = 'activity_txn_trigger') then
    create trigger activity_txn_trigger
      after insert or update or delete on transactions
      for each row execute function public.log_domain_activity();
  end if;

  if not exists (select 1 from pg_trigger where tgname = 'activity_budgets_trigger') then
    create trigger activity_budgets_trigger
      after insert or update or delete on budgets
      for each row execute function public.log_domain_activity();
  end if;

  if not exists (select 1 from pg_trigger where tgname = 'activity_goals_trigger') then
    create trigger activity_goals_trigger
      after insert or update or delete on goals
      for each row execute function public.log_domain_activity();
  end if;

  if not exists (select 1 from pg_trigger where tgname = 'activity_debts_trigger') then
    create trigger activity_debts_trigger
      after insert or update or delete on debts
      for each row execute function public.log_domain_activity();
  end if;

  if not exists (select 1 from pg_trigger where tgname = 'activity_assets_trigger') then
    create trigger activity_assets_trigger
      after insert or update or delete on assets
      for each row execute function public.log_domain_activity();
  end if;

  if not exists (select 1 from pg_trigger where tgname = 'activity_memberships_trigger') then
    create trigger activity_memberships_trigger
      after insert or update or delete on memberships
      for each row execute function public.log_domain_activity();
  end if;
end$$;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260529151000_td09_replace_all_rpcs.sql
-- ─────────────────────────────────────────────────────────────────────
-- TD-09 — atomic `replace_<entity>(h uuid, rows jsonb)` RPCs for bulk import.
--
-- Each function soft-deletes existing rows for the household and inserts
-- the provided rows in one transaction, returning the inserted set. Every
-- RPC is SECURITY DEFINER and gated by:
--   • auth.uid() must be set
--   • is_member(h) must be true
-- so a signed-in member of one household can't import into another.
--
-- The pre-PR-#16 design intent for this lived at
-- db/migrations-superseded/20260524073000_replace_all_rpc.sql but was
-- never applied to prod. This migration re-lands it through the
-- validated auto-apply pipeline. It depends on TD-13's period columns
-- (see 20260529150000_td13_budgets_add_period.sql which sorts first),
-- so the budgets replace function can use them.

begin;

-- ── transactions ─────────────────────────────────────────────────
create or replace function public.replace_transactions(h uuid, rows jsonb)
returns setof transactions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Must be signed in'; end if;
  if not is_member(h) then raise exception 'Not a member of this household'; end if;

  update transactions set deleted_at = now() where household_id = h and deleted_at is null;

  return query
  insert into transactions (id, household_id, created_by, member_id, type, amount, currency, date, description, category, note, recurring, attachment_url, extras, created_at, updated_at, deleted_at)
  select t.id::uuid, h, t.created_by::uuid, t.member_id::uuid, t.type, t.amount::numeric, t.currency, t.date::date, t.description, t.category, t.note, t.recurring, t.attachment_url, t.extras::jsonb, t.created_at::timestamptz, t.updated_at::timestamptz, t.deleted_at::timestamptz
  from jsonb_populate_recordset(null::transactions, rows) as t;
end;
$$;
grant execute on function public.replace_transactions(uuid, jsonb) to authenticated;

-- ── budgets ──────────────────────────────────────────────────────
create or replace function public.replace_budgets(h uuid, rows jsonb)
returns setof budgets
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Must be signed in'; end if;
  if not is_member(h) then raise exception 'Not a member of this household'; end if;

  update budgets set deleted_at = now() where household_id = h and deleted_at is null;

  return query
  insert into budgets (id, household_id, category, monthly_limit, currency, color, period, period_start, period_end, created_at, updated_at, deleted_at)
  select t.id::uuid, h, t.category, t.monthly_limit::numeric, t.currency, t.color, t.period, t.period_start::date, t.period_end::date, t.created_at::timestamptz, t.updated_at::timestamptz, t.deleted_at::timestamptz
  from jsonb_populate_recordset(null::budgets, rows) as t;
end;
$$;
grant execute on function public.replace_budgets(uuid, jsonb) to authenticated;

-- ── goals ────────────────────────────────────────────────────────
create or replace function public.replace_goals(h uuid, rows jsonb)
returns setof goals
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Must be signed in'; end if;
  if not is_member(h) then raise exception 'Not a member of this household'; end if;

  update goals set deleted_at = now() where household_id = h and deleted_at is null;

  return query
  insert into goals (id, household_id, type, name, target_amount, current_amount, currency, deadline, completed, created_at, updated_at, deleted_at)
  select t.id::uuid, h, t.type, t.name, t.target_amount::numeric, t.current_amount::numeric, t.currency, t.deadline::date, t.completed::boolean, t.created_at::timestamptz, t.updated_at::timestamptz, t.deleted_at::timestamptz
  from jsonb_populate_recordset(null::goals, rows) as t;
end;
$$;
grant execute on function public.replace_goals(uuid, jsonb) to authenticated;

-- ── debts ────────────────────────────────────────────────────────
create or replace function public.replace_debts(h uuid, rows jsonb)
returns setof debts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Must be signed in'; end if;
  if not is_member(h) then raise exception 'Not a member of this household'; end if;

  update debts set deleted_at = now() where household_id = h and deleted_at is null;

  return query
  insert into debts (id, household_id, type, name, lender, account_last4, principal, current_balance, interest_rate, minimum_payment, due_date, currency, extras, created_at, updated_at, deleted_at)
  select t.id::uuid, h, t.type, t.name, t.lender, t.account_last4, t.principal::numeric, t.current_balance::numeric, t.interest_rate::numeric, t.minimum_payment::numeric, t.due_date::date, t.currency, t.extras::jsonb, t.created_at::timestamptz, t.updated_at::timestamptz, t.deleted_at::timestamptz
  from jsonb_populate_recordset(null::debts, rows) as t;
end;
$$;
grant execute on function public.replace_debts(uuid, jsonb) to authenticated;

-- ── assets ───────────────────────────────────────────────────────
create or replace function public.replace_assets(h uuid, rows jsonb)
returns setof assets
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Must be signed in'; end if;
  if not is_member(h) then raise exception 'Not a member of this household'; end if;

  update assets set deleted_at = now() where household_id = h and deleted_at is null;

  return query
  insert into assets (id, household_id, type, name, value, currency, liquidity, note, last_updated, created_at, updated_at, deleted_at)
  select t.id::uuid, h, t.type, t.name, t.value::numeric, t.currency, t.liquidity, t.note, t.last_updated::date, t.created_at::timestamptz, t.updated_at::timestamptz, t.deleted_at::timestamptz
  from jsonb_populate_recordset(null::assets, rows) as t;
end;
$$;
grant execute on function public.replace_assets(uuid, jsonb) to authenticated;

-- ── memberships ──────────────────────────────────────────────────
-- Memberships have no `deleted_at` column in the baseline (membership
-- removal is a hard delete with cascade implications). We match that
-- pattern instead of soft-deleting.
create or replace function public.replace_memberships(h uuid, rows jsonb)
returns setof memberships
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Must be signed in'; end if;
  if not is_member(h) then raise exception 'Not a member of this household'; end if;

  delete from memberships where household_id = h;

  return query
  insert into memberships (id, household_id, user_id, role, display_name, household_role, joined_at)
  select t.id::uuid, h, t.user_id::uuid, t.role, t.display_name, t.household_role, t.joined_at::timestamptz
  from jsonb_populate_recordset(null::memberships, rows) as t;
end;
$$;
grant execute on function public.replace_memberships(uuid, jsonb) to authenticated;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260529151500_td08_td09_harden_execute_grants.sql
-- ─────────────────────────────────────────────────────────────────────
-- TD-08 / TD-09 follow-up — revoke the default PUBLIC execute grant on the
-- SECURITY DEFINER functions added earlier in this PR.
--
-- Postgres grants EXECUTE to PUBLIC by default on every new function. The
-- TD-09 migration added `grant execute ... to authenticated` for the six
-- replace_<entity> RPCs but did not revoke the implicit PUBLIC grant, so
-- the `anon` role could still reach them (the in-function `auth.uid() is
-- null` guard rejected such calls, but defense-in-depth says don't expose
-- the entrypoint at all). The TD-08 trigger function log_domain_activity()
-- is never meant to be called directly as an RPC — triggers fire as the
-- table owner regardless of EXECUTE grant — so it should be callable by
-- nobody.
--
-- This migration was authored after the Supabase security advisor flagged
-- the seven functions under lints 0028 / 0029. It clears the anon exposure
-- and the trigger-function exposure. The remaining advisor entries for the
-- replace_* RPCs under the `authenticated` role are intentional and match
-- the existing posture of is_member / accept_invitation / admin_* — signed-in
-- household members must be able to call them, and each carries its own
-- auth.uid() + is_member(h) guard.

begin;

-- Trigger function: callable by nobody as an RPC.
revoke execute on function public.log_domain_activity() from public, anon, authenticated;

-- Atomic bulk-replace RPCs: keep the authenticated grant from the TD-09
-- migration; drop the implicit PUBLIC grant so anon cannot reach them.
revoke execute on function public.replace_transactions(uuid, jsonb) from public, anon;
revoke execute on function public.replace_budgets(uuid, jsonb)      from public, anon;
revoke execute on function public.replace_goals(uuid, jsonb)        from public, anon;
revoke execute on function public.replace_debts(uuid, jsonb)        from public, anon;
revoke execute on function public.replace_assets(uuid, jsonb)       from public, anon;
revoke execute on function public.replace_memberships(uuid, jsonb)  from public, anon;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260601120000_td06_td21_rls_perf_and_delta_sync_indexes.sql
-- ─────────────────────────────────────────────────────────────────────
-- TD-21 (RLS performance) + TD-06 (delta-sync indexes) — paired migration.
--
-- Two Supabase Performance Advisor finding-classes are addressed here, plus
-- the index prerequisite for the TD-06 client-side delta-sync redesign.
--
-- ─── TD-21a · auth_rls_initplan ──────────────────────────────────────────
--   Several baseline policies call `auth.uid()` directly in the USING /
--   WITH CHECK expression. Postgres treats that as a row-dependent function
--   reference and re-evaluates it for every candidate row instead of caching
--   it as an initplan. Wrapping it as `(select auth.uid())` lets the planner
--   recognise it as a constant for the query and reduces RLS overhead from
--   O(rows) to O(1).
--
-- ─── TD-21b · multiple_permissive_policies ───────────────────────────────
--   Every domain table (transactions / budgets / goals / debts / assets)
--   carries TWO permissive SELECT policies for `authenticated`:
--     - "<table>_read"                         (household membership check)
--     - "admins read all <table>"              (is_admin('roles'))
--   Postgres OR-merges permissive policies, but each is still planned and
--   evaluated. Consolidating into a single policy with an OR-ed predicate
--   removes one full RLS evaluation per row per query. Same pattern is
--   applied to `memberships`, `profiles`, `exchange_rates`, `subscriptions`,
--   and `activity_log` which all carry overlapping select policies.
--
--   The new SELECT policies use the existing SECURITY DEFINER helpers
--   (`is_member`, `is_admin`) which (a) already wrap `auth.uid()` cleanly,
--   (b) are STABLE so the planner can memoise them, and (c) bypass RLS on
--   the `memberships` lookup so the policy can't recurse. The old hand-
--   inlined `exists (...)` form re-introduced the unwrapped `auth.uid()`
--   problem on every row.
--
-- ─── TD-06 · delta-sync index prerequisite ───────────────────────────────
--   The consumer adapter is moving from "pull the whole table" to "pull
--   rows where `updated_at > cursor` ordered by `updated_at`". The
--   transactions table already has `txns_updated_idx (household_id,
--   updated_at)`; this migration adds the matching composite index to the
--   other four domain tables so the new query path is index-served on day
--   one.
--
-- Idempotency: every statement uses `drop policy if exists` and
-- `create index if not exists`. Safe to re-run.

BEGIN;

-- ── transactions ─────────────────────────────────────────────────────────
drop policy if exists "transactions_read"            on transactions;
drop policy if exists "admins read all transactions" on transactions;
create policy "transactions_read" on transactions for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

-- ── budgets ──────────────────────────────────────────────────────────────
drop policy if exists "budgets_read"             on budgets;
drop policy if exists "admins read all budgets"  on budgets;
create policy "budgets_read" on budgets for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

-- ── goals ────────────────────────────────────────────────────────────────
drop policy if exists "goals_read"               on goals;
drop policy if exists "admins read all goals"    on goals;
create policy "goals_read" on goals for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

-- ── debts ────────────────────────────────────────────────────────────────
drop policy if exists "debts_read"               on debts;
drop policy if exists "admins read all debts"    on debts;
create policy "debts_read" on debts for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

-- ── assets ───────────────────────────────────────────────────────────────
drop policy if exists "assets_read"              on assets;
drop policy if exists "admins read all assets"   on assets;
create policy "assets_read" on assets for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

-- ── exchange_rates ───────────────────────────────────────────────────────
-- Replaces the inline `exists (... user_id = auth.uid())` membership check
-- with the cached helper. Single SELECT policy already; just the RLS-init
-- plan rewrite.
drop policy if exists "rates_read" on exchange_rates;
create policy "rates_read" on exchange_rates for select to authenticated
  using (is_member(household_id));

-- ── memberships ──────────────────────────────────────────────────────────
-- Overlapping SELECT pair → single consolidated policy.
drop policy if exists "members see other members"    on memberships;
drop policy if exists "admins read all memberships"  on memberships;
create policy "memberships_read" on memberships for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

-- "members leave; owners remove non-owners" uses bare auth.uid() — wrap.
drop policy if exists "members leave; owners remove non-owners" on memberships;
create policy "members leave; owners remove non-owners" on memberships for delete to authenticated
  using (user_id = (select auth.uid())
         or role_in(household_id) = 'owner'
         or (role_in(household_id) = 'admin' and role <> 'owner'));

-- ── profiles ─────────────────────────────────────────────────────────────
-- Three overlapping SELECT policies + a self-update policy with bare
-- auth.uid(). Consolidate the reads; wrap the writer.
drop policy if exists "users read own profile"             on profiles;
drop policy if exists "users read profiles of co-members"  on profiles;
drop policy if exists "admins read all profiles"           on profiles;
create policy "profiles_read" on profiles for select to authenticated
  using (
    id = (select auth.uid())
    or is_admin('roles')
    or id in (
      select m2.user_id
      from memberships m1
      join memberships m2 on m1.household_id = m2.household_id
      where m1.user_id = (select auth.uid())
    )
  );

drop policy if exists "users update own profile" on profiles;
create policy "users update own profile" on profiles for update to authenticated
  using (id = (select auth.uid()));

-- ── households ───────────────────────────────────────────────────────────
-- "anyone create household" uses bare auth.uid() — wrap. The other
-- households policies use the cached helpers; leave them alone.
drop policy if exists "anyone create household" on households;
create policy "anyone create household" on households for insert to authenticated
  with check (created_by = (select auth.uid()));

-- ── activity_log ─────────────────────────────────────────────────────────
-- Overlapping SELECT pair + bare auth.uid() in the membership form.
drop policy if exists "log_read"                  on activity_log;
drop policy if exists "admins read all activity"  on activity_log;
create policy "activity_log_read" on activity_log for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

-- ── admin_roles ──────────────────────────────────────────────────────────
drop policy if exists "self read admin_roles" on admin_roles;
create policy "self read admin_roles" on admin_roles for select to authenticated
  using (user_id = (select auth.uid()));

-- ── ai_usage ─────────────────────────────────────────────────────────────
drop policy if exists "ai_usage_insert" on ai_usage;
create policy "ai_usage_insert" on ai_usage for insert to authenticated
  with check (is_member(household_id) and user_id = (select auth.uid()));

-- ── content_favorites ────────────────────────────────────────────────────
drop policy if exists "self favorites delete" on content_favorites;
drop policy if exists "self favorites insert" on content_favorites;
drop policy if exists "self favorites read"   on content_favorites;
create policy "self favorites delete" on content_favorites for delete to authenticated
  using (user_id = (select auth.uid()));
create policy "self favorites insert" on content_favorites for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "self favorites read"   on content_favorites for select to authenticated
  using (user_id = (select auth.uid()));

-- ── subscriptions ────────────────────────────────────────────────────────
drop policy if exists "self read subscriptions" on subscriptions;
create policy "self read subscriptions" on subscriptions for select to authenticated
  using (user_id = (select auth.uid()) or is_admin('roles'));

-- ── invitations ──────────────────────────────────────────────────────────
-- "owners and admins send invitations" embeds bare auth.uid().
drop policy if exists "owners and admins send invitations" on invitations;
create policy "owners and admins send invitations" on invitations for insert to authenticated
  with check (role_in(household_id) in ('owner','admin') and invited_by = (select auth.uid()));

-- ── TD-06 · composite indexes for `updated_at > cursor` delta pulls ──────
create index if not exists budgets_household_updated_idx on budgets (household_id, updated_at);
create index if not exists goals_household_updated_idx   on goals   (household_id, updated_at);
create index if not exists debts_household_updated_idx   on debts   (household_id, updated_at);
create index if not exists assets_household_updated_idx  on assets  (household_id, updated_at);
-- transactions already has `txns_updated_idx (household_id, updated_at)`.

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260601153000_fix_shareable_invite_accept_rpc.sql
-- ─────────────────────────────────────────────────────────────────────
create or replace function public.accept_invitation_link(invite_token text)
  returns jsonb
  language plpgsql
  security definer
  set search_path to 'public'
as $$
declare
  inv invitations%rowtype;
  caller_email text;
  existing memberships%rowtype;
  new_membership_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Must be signed in to accept an invitation';
  end if;

  select email into caller_email from auth.users where id = auth.uid();

  select * into inv
  from invitations
  where token = invite_token
    and accepted_at is null
    and expires_at > now();

  if not found then
    raise exception 'Invitation not found or expired';
  end if;

  select * into existing
  from memberships
  where household_id = inv.household_id
    and user_id = auth.uid();

  if found then
    update invitations set accepted_at = now() where id = inv.id;
    return jsonb_build_object(
      'household_id', inv.household_id,
      'membership_id', existing.id,
      'role', existing.role,
      'already_member', true
    );
  end if;

  insert into memberships (household_id, user_id, role, display_name, household_role)
  values (
    inv.household_id,
    auth.uid(),
    inv.role,
    coalesce((select display_name from profiles where id = auth.uid()), split_part(coalesce(caller_email, ''), '@', 1), 'member'),
    coalesce(inv.household_role, 'member')
  )
  returning id into new_membership_id;

  update invitations set accepted_at = now() where id = inv.id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id)
  values (inv.household_id, auth.uid(), 'accepted', 'invitation', inv.id);

  return jsonb_build_object(
    'household_id', inv.household_id,
    'membership_id', new_membership_id,
    'role', inv.role,
    'already_member', false
  );
end;
$$;

revoke all on function public.accept_invitation_link(text) from public;
grant execute on function public.accept_invitation_link(text) to authenticated;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260602120000_money_map_phase1_accounts.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money Map · Phase 1 — first-class accounts + transaction FKs + debt direction
--
-- Spec: docs/SOLUTION_MONEY_MAP.md (v7.2 Migration A).
-- Target rollout: shadow → on → cutover across v7.2.0-rc / v7.2.1 / v7.3.0.
--
-- Design rules:
--   1. ADDITIVE ONLY. No DROP, no column type changes, no data destruction.
--   2. Idempotent. `create … if not exists` / `add column if not exists` /
--      `create or replace view`. Safe to re-run.
--   3. RLS for new tables MIRRORS the existing transactions/debts/assets
--      shape (`is_member` / `is_admin` helpers from TD-21) — no new
--      auth surface, no new SECURITY DEFINER functions introduced here.
--   4. Backfill is split into a separate file so this one can be applied
--      without touching existing rows.
--
-- Pre-flight (manual):
--   • Take a Supabase database backup (Dashboard → Database → Backups,
--     or `pg_dump`). The migration is non-destructive but a known restore
--     point is the safety net the spec recommends.
--   • Verify the TD-21 helpers exist (`is_member(uuid)`, `is_admin(text)`)
--     — they're prerequisites for the policy bodies below.

BEGIN;

-- ─── 1. accounts table (Items #2 + #5) ───────────────────────────────────

create table if not exists accounts (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references households(id) on delete cascade,
  asset_id      uuid references assets(id) on delete set null,
  kind          text not null check (kind in
                  ('checking','savings','credit_card','cash',
                   'investment','wallet','other')),
  name          text not null,
  currency      char(3) not null,
  is_default    boolean not null default false,
  is_archived   boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  deleted_at    timestamptz
);

-- One default account per (household, currency) — only when active.
create unique index if not exists accounts_default_per_currency
  on accounts (household_id, currency)
  where is_default and not is_archived and deleted_at is null;

create index if not exists accounts_household
  on accounts (household_id) where not is_archived and deleted_at is null;

-- Delta-sync index (matches TD-06 pattern from other domain tables).
create index if not exists accounts_updated_idx
  on accounts (household_id, updated_at);

-- ─── 2. transactions ↔ accounts FK columns (Item #5) ─────────────────────

alter table transactions
  add column if not exists account_id     uuid references accounts(id) on delete set null,
  add column if not exists to_account_id  uuid references accounts(id) on delete set null,
  add column if not exists initiated_by   uuid references memberships(id) on delete set null;

create index if not exists transactions_account
  on transactions (household_id, account_id) where account_id is not null;
create index if not exists transactions_to_account
  on transactions (household_id, to_account_id) where to_account_id is not null;
create index if not exists transactions_initiated_by
  on transactions (household_id, initiated_by) where initiated_by is not null;

-- ─── 3. debt direction (Item #3 — bidirectional / lending) ──────────────

alter table debts
  add column if not exists direction text not null default 'owed_by_me'
    check (direction in ('owed_by_me','owed_to_me')),
  add column if not exists counterparty_name text;

-- Active debts only — the partial index keeps it lean for the typical
-- "what do I owe / who owes me" filter.
create index if not exists debts_direction
  on debts (household_id, direction) where deleted_at is null;

-- ─── 4. server-side aggregates (Item #8) ────────────────────────────────
--
-- Views inherit RLS from the base table (Postgres 14+ — `security_invoker`
-- is the default for views in pg14+). The `where excluded is not true`
-- predicate matches client-side `reportableTxns` semantics so client and
-- server reports stay byte-identical.
--
-- WARNING: every read of these views MUST scope by `household_id` so the
-- planner can use `transactions_account` / `transactions_initiated_by`
-- as the leading index. A bare `select * from v_txn_by_member` will
-- table-scan; lint at PR review (per Sec-3 in the spec).

create or replace view v_txn_by_member as
  select t.household_id,
         t.initiated_by                          as member_id,
         date_trunc('month', t.date)             as period,
         t.type,
         t.currency,
         sum(t.amount)                           as total,
         count(*)                                as n
    from transactions t
   where t.deleted_at is null
     and (t.extras is null or coalesce((t.extras->>'excluded')::boolean, false) = false)
   group by 1, 2, 3, 4, 5;

create or replace view v_txn_by_account as
  select t.household_id,
         t.account_id,
         date_trunc('month', t.date)             as period,
         t.type,
         t.currency,
         sum(t.amount)                           as total,
         count(*)                                as n
    from transactions t
   where t.deleted_at is null
     and (t.extras is null or coalesce((t.extras->>'excluded')::boolean, false) = false)
   group by 1, 2, 3, 4, 5;

-- ─── 5. RLS for new tables (mirrors transactions policy shape) ──────────

alter table accounts enable row level security;

drop policy if exists "accounts_read"   on accounts;
drop policy if exists "accounts_insert" on accounts;
drop policy if exists "accounts_update" on accounts;
drop policy if exists "accounts_delete" on accounts;

create policy "accounts_read" on accounts for select to authenticated
  using (is_member(household_id) or is_admin('roles'));

create policy "accounts_insert" on accounts for insert to authenticated
  with check (role_in(household_id) in ('owner','admin','member'));

create policy "accounts_update" on accounts for update to authenticated
  using (role_in(household_id) in ('owner','admin','member'))
  with check (role_in(household_id) in ('owner','admin','member'));

create policy "accounts_delete" on accounts for delete to authenticated
  using (role_in(household_id) in ('owner','admin'));

-- ─── 6. updated_at trigger (matches the convention on every other table) ─

create or replace function set_updated_at_accounts()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_accounts_updated_at on accounts;
create trigger trg_accounts_updated_at
  before update on accounts
  for each row execute function set_updated_at_accounts();

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260602120100_money_map_phase1_backfill.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money Map · Phase 1 backfill — synthesise `accounts` rows from existing
-- `assets` and link `transactions.account_id` to the new rows.
--
-- Spec: docs/SOLUTION_MONEY_MAP.md → "Backfill (idempotent, runs once per
-- household)". Split out from the schema migration so it can be rerun
-- safely without re-touching DDL, and so the schema can ship to staging
-- without paying the backfill cost there.
--
-- Idempotency:
--   • The accounts INSERT is gated by NOT EXISTS on (household_id, asset_id).
--   • The transactions UPDATE only writes where `account_id IS NULL`.
--   • Run twice → identical row counts (acceptance gate #3 of v7.2).
--
-- Operational guidance for large tenants:
--   • Wrap each tenant in its own transaction by filtering on a single
--     `household_id` if the global form holds locks too long. The default
--     form below is fine up to ~1 M transaction rows.
--   • Run during the v7.2.0-rc 'shadow' window — the app is still reading
--     legacy `linked_asset_id` so any backfill correctness issue is
--     observable in dual-read assertions before flipping to 'on'.

BEGIN;

-- ─── 1. accounts derived from spendable / liquid asset rows ─────────────
--
-- Only the four asset types that map to a real spending surface get an
-- account synthesised. Investment / property / vehicle assets do NOT
-- become accounts here — they remain assets and join the accounts table
-- only when the user explicitly creates an "investment" account in the
-- v7.2 UI. (Per spec U-2: keeps the account list bounded.)

insert into accounts (household_id, asset_id, kind, name, currency, is_default)
select a.household_id,
       a.id,
       case a.type
         when 'checking'    then 'checking'
         when 'savings'     then 'savings'
         when 'credit_card' then 'credit_card'
         when 'cash'        then 'cash'
         else 'other'
       end                                                            as kind,
       a.name,
       a.currency,
       -- The largest-balance asset per (household, currency) wins
       -- the is_default flag; ties broken by created_at desc.
       (row_number() over (
          partition by a.household_id, a.currency
              order by a.value desc, a.created_at desc
        ) = 1)                                                        as is_default
  from assets a
 where a.type in ('checking','savings','credit_card','cash')
   and a.deleted_at is null
   and not exists (
     select 1 from accounts ac
      where ac.household_id = a.household_id
        and ac.asset_id     = a.id
   );

-- ─── 2. link existing transactions to the new account rows ──────────────
--
-- Reads `extras->>'linkedAssetId'` (the v7.0.3 client-side key) and
-- `extras->>'linkedToAssetId'` (added in v7.0.3 for transfer / investment
-- destinations). Resolves both to the matching account_id.

update transactions t
   set account_id = ac.id
  from accounts ac
 where ac.household_id = t.household_id
   and ac.asset_id     = nullif(t.extras->>'linkedAssetId', '')::uuid
   and t.account_id is null;

update transactions t
   set to_account_id = ac.id
  from accounts ac
 where ac.household_id = t.household_id
   and ac.asset_id     = nullif(t.extras->>'linkedToAssetId', '')::uuid
   and t.to_account_id is null;

-- `member_id` already exists on transactions for the v7.0 work; copy it
-- across to `initiated_by` so the new aggregate views see historical rows.
update transactions
   set initiated_by = member_id
 where initiated_by is null
   and member_id    is not null;

-- ─── 3. debts direction default ────────────────────────────────────────
-- Schema default is 'owed_by_me' (the existing semantic) so no UPDATE is
-- needed. Counterparty_name is left null; users fill it in only when
-- they create a new lending row in v7.2 UI.

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260602120200_money_map_education_progress.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money Map · Phase 2 — education progress sync (Item #7)
--
-- Spec: docs/SOLUTION_MONEY_MAP.md → "v7.2 Migration B".
-- Trivial additive jsonb column on `profiles`; inherits existing RLS.
--
-- Shape:
--   { "<topic_id>": { "completed_at": iso8601, "dismissed_at": iso8601? } }
--
-- App caps the map at 50 keys (Risk S-3) and prunes on write.

BEGIN;

alter table profiles
  add column if not exists education_progress jsonb not null default '{}'::jsonb;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260602130000_money_map_replace_accounts_rpc.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money Map · v7.2 — replace_accounts RPC.
--
-- Mirrors `replace_assets` (TD-09 pattern). Required by the
-- `HybridAdapter.replaceAll('accounts', ...)` path so bulk import /
-- restore works once accounts are first-class.
--
-- Idempotent (`create or replace`). Soft-delete + insert inside a single
-- transaction so partial failures roll back. SECURITY DEFINER with the
-- same `is_member` guard the other replace_* functions use.

BEGIN;

create or replace function public.replace_accounts(h uuid, rows jsonb)
returns setof accounts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Must be signed in'; end if;
  if not is_member(h) then raise exception 'Not a member of this household'; end if;

  update accounts set deleted_at = now() where household_id = h and deleted_at is null;

  return query
  insert into accounts (
    id, household_id, asset_id, kind, name, currency,
    is_default, is_archived, created_at, updated_at, deleted_at
  )
  select
    t.id::uuid, h, t.asset_id::uuid, t.kind, t.name, t.currency,
    coalesce(t.is_default, false),
    coalesce(t.is_archived, false),
    coalesce(t.created_at::timestamptz, now()),
    coalesce(t.updated_at::timestamptz, now()),
    t.deleted_at::timestamptz
  from jsonb_populate_recordset(null::accounts, rows) as t;
end;
$$;

-- Lock down execute grants the same way TD-09 does for every other
-- replace_* function (see 20260529151500_td08_td09_harden_execute_grants.sql).
revoke execute on function public.replace_accounts(uuid, jsonb) from public, anon;
grant  execute on function public.replace_accounts(uuid, jsonb) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260602140000_money_map_saved_views.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money Map · Phase 3 — saved filter views (Item #4)
--
-- Spec: docs/SOLUTION_MONEY_MAP.md → "v7.3 Migration C".
-- Per-user, per-page filter snapshots that survive across devices.
-- Sharing is opt-in at the row level (`is_shared = true`) and limited
-- to the owner's household via the second policy.
--
-- Sec-2 (privacy): the `filters` jsonb is sanitised app-side before
-- save — only filter parameters ever leak into a shared view, never
-- transaction ids, member ids, or descriptions. The DB does not enforce
-- the shape; the app does. This mirrors the `extras` discipline on
-- `transactions`.
--
-- Run order: after 20260529151500_td08_td09_harden_execute_grants.sql
-- (depends on `is_member` / `is_admin` helpers).

BEGIN;

-- ─── 1. Table ───────────────────────────────────────────────────────────
create table if not exists saved_views (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  household_id  uuid not null references households(id) on delete cascade,
  page          text not null check (page in ('transactions','reports','insights')),
  name          text not null,
  filters       jsonb not null default '{}'::jsonb,
  is_shared     boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  deleted_at    timestamptz
);

create index if not exists saved_views_user
  on saved_views (user_id, page) where deleted_at is null;

create index if not exists saved_views_household_shared
  on saved_views (household_id, page)
  where is_shared and deleted_at is null;

-- ─── 2. updated_at trigger ──────────────────────────────────────────────
create or replace function public.tg_saved_views_touch_updated_at()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists saved_views_touch_updated_at on saved_views;
create trigger saved_views_touch_updated_at
  before update on saved_views
  for each row execute function public.tg_saved_views_touch_updated_at();

-- ─── 3. RLS ─────────────────────────────────────────────────────────────
alter table saved_views enable row level security;

drop policy if exists "saved_views_self"             on saved_views;
drop policy if exists "saved_views_household_shared" on saved_views;
drop policy if exists "saved_views_insert"           on saved_views;
drop policy if exists "saved_views_update"           on saved_views;
drop policy if exists "saved_views_delete"           on saved_views;

-- Owner sees their own rows always.
create policy "saved_views_self" on saved_views for select to authenticated
  using (user_id = auth.uid() or is_admin('roles'));

-- Other household members see rows the owner explicitly shared.
create policy "saved_views_household_shared" on saved_views for select to authenticated
  using (is_shared and is_member(household_id));

-- Owner-only writes. Members do NOT inherit edit rights on shared rows.
create policy "saved_views_insert" on saved_views for insert to authenticated
  with check (user_id = auth.uid() and is_member(household_id));

create policy "saved_views_update" on saved_views for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy "saved_views_delete" on saved_views for delete to authenticated
  using (user_id = auth.uid());

-- ─── 4. replace_saved_views RPC (TD-09 family) ──────────────────────────
-- Note: scoped to (household, user) — we never wipe another user's saved
-- views. Bulk-replace stays per-owner.
create or replace function public.replace_saved_views(h uuid, rows jsonb)
returns setof saved_views
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then
    raise exception 'Must be signed in';
  end if;
  if not is_member(h) then
    raise exception 'Not a member of this household';
  end if;

  update saved_views
     set deleted_at = now()
   where household_id = h
     and user_id = auth.uid()
     and deleted_at is null;

  return query
  insert into saved_views (id, user_id, household_id, page, name, filters, is_shared, created_at, updated_at, deleted_at)
  select coalesce(t.id, gen_random_uuid()),
         auth.uid(),
         h,
         t.page,
         t.name,
         coalesce(t.filters, '{}'::jsonb),
         coalesce(t.is_shared, false),
         coalesce(t.created_at, now()),
         coalesce(t.updated_at, now()),
         t.deleted_at
    from jsonb_populate_recordset(null::saved_views, rows) as t;
end;
$$;

revoke execute on function public.replace_saved_views(uuid, jsonb) from public;
revoke execute on function public.replace_saved_views(uuid, jsonb) from anon;
grant  execute on function public.replace_saved_views(uuid, jsonb) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260603210000_money_map_views_security_invoker.sql
-- ─────────────────────────────────────────────────────────────────────
-- SECURITY FIX (post-v7.4.0 advisor) — Money Map aggregate views must respect RLS.
--
-- `v_txn_by_member` and `v_txn_by_account` (added in
-- 20260602120000_money_map_phase1_accounts.sql) were created WITHOUT
-- `security_invoker`, so in Postgres they ran with the view owner's
-- privileges and BYPASSED row-level security. Their bodies select from
-- `transactions` with no household filter, so any authenticated user could
-- query `/rest/v1/v_txn_by_member` / `/rest/v1/v_txn_by_account` and read
-- transaction aggregates across EVERY household — a cross-tenant data leak.
-- (Flagged ERROR `security_definer_view` 0010 by the Supabase advisor.)
--
-- Setting `security_invoker = on` makes each view run with the querying
-- user's privileges, so the existing `transactions` RLS
-- (`is_member(household_id)`) scopes results to the caller's own households.
-- This is also the behaviour the Reports breakouts already assume.

alter view public.v_txn_by_member  set (security_invoker = on);
alter view public.v_txn_by_account set (security_invoker = on);

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260606120000_v8_onboarding_state.sql
-- ─────────────────────────────────────────────────────────────────────
-- v8.0.0 · Onboarding & Activation — cloud persistence
--
-- Spec: vyact-onboarding-engineering-spec.md (§2 per-household state, §3 data
-- model + provenance, §5 temporary-baseline lifecycle).
--
-- v8.0.0 shipped onboarding state as browser-local overlays, which made the
-- honest-data lifecycle device-local (a second device, or a cleared cache, lost
-- the "estimated" tags, the % confirmed indicator, the 21-day window, and nudge
-- bookkeeping). This migration promotes both halves to the cloud:
--
--   (a) PER-HOUSEHOLD STATE  → households.onboarding (jsonb). Mirrors the
--       Money-Map education_progress precedent: a trivial additive jsonb column
--       on the per-household table, inheriting the existing households RLS.
--
--   (b) RECORD PROVENANCE    → normalized confidence/source/estimated_at/
--       confirmed_at columns on every baseline-derived entity (transactions,
--       budgets, goals, debts, assets). Provenance therefore rides the existing
--       per-entity sync + RLS, is queryable in SQL, and stays attached to the
--       row it describes. Defaults ('confirmed' / 'user') mean every existing
--       row and every ordinary user row is first-class with no backfill, and
--       existing data is NEVER re-tagged as an estimate (spec §3.4).
--
-- households.onboarding shape (validated app-side; schemaless so the flow can
-- evolve without a migration per change):
--   {
--     "state": "not_started|in_progress|completed|skipped",
--     "segment": "individual|household|smb"|null,
--     "context": { ... }|null,
--     "currentStep": 0,
--     "startedAt": iso8601|null,
--     "completedAt": iso8601|null,
--     "confirmationWindowEndsAt": iso8601|null   -- completedAt + 21 days
--   }

BEGIN;

-- ── (a) per-household onboarding state ────────────────────────────────────────
alter table households
  add column if not exists onboarding jsonb not null default '{}'::jsonb;

alter table households
  drop constraint if exists households_onboarding_is_object;
alter table households
  add constraint households_onboarding_is_object
  check (jsonb_typeof(onboarding) = 'object');

comment on column households.onboarding is
  'v8 Onboarding & Activation per-household state machine record. See vyact-onboarding-engineering-spec.md §2/§3.';

-- ── (b) per-entity provenance columns ─────────────────────────────────────────
-- Applied to each baseline-derived table via a do-block so the checks/comments
-- stay DRY. confidence/source default to the first-class values so legacy rows
-- and ordinary user writes need no backfill.
do $$
declare
  t text;
  tables text[] := array['transactions','budgets','goals','debts','assets'];
begin
  foreach t in array tables loop
    execute format($f$
      alter table %I
        add column if not exists confidence   text        not null default 'confirmed',
        add column if not exists source        text       not null default 'user',
        add column if not exists estimated_at  timestamptz,
        add column if not exists confirmed_at  timestamptz;
    $f$, t);

    execute format($f$
      alter table %1$I drop constraint if exists %1$s_confidence_chk;
      alter table %1$I add  constraint %1$s_confidence_chk
        check (confidence in ('estimated','confirming','confirmed'));
      alter table %1$I drop constraint if exists %1$s_source_chk;
      alter table %1$I add  constraint %1$s_source_chk
        check (source in ('onboarding','user','bank'));
    $f$, t);

    -- Partial index: cheaply find the still-outstanding onboarding estimates a
    -- household has to confirm during the 21-day window (powers the nudge stats
    -- and a future server-side % confirmed). Excludes the confirmed majority.
    execute format($f$
      create index if not exists %1$s_estimated_idx
        on %1$I (household_id)
        where confidence <> 'confirmed';
    $f$, t);

    execute format($f$
      comment on column %I.confidence is
        'v8 honest-data confidence: estimated|confirming|confirmed (spec §3.2/§5).';
    $f$, t);
  end loop;
end $$;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260606130000_v8_fix_my_households_view.sql
-- ─────────────────────────────────────────────────────────────────────
-- v8.0.2 hotfix — expose households.onboarding through the my_households view.
--
-- 20260606120000_v8_onboarding_state.sql added households.onboarding, but the
-- my_households view had been created with an EXPANDED column list (Postgres
-- freezes `select h.*` into explicit columns at creation time). Adding a column
-- to the base table therefore did NOT add it to the view, so the consumer's
-- `GET /rest/v1/my_households?select=...,onboarding` returned 400 and blocked the
-- entire app on load (listHouseholds runs during init).
--
-- A view's column set cannot be reordered/extended in the middle via CREATE OR
-- REPLACE, so we DROP and recreate. Confirmed no other view depends on it.
-- Recreating re-expands h.* to the current household columns (incl. onboarding
-- and baseline_provenance). security_invoker + grant restored to match the
-- original definition.

BEGIN;

drop view if exists my_households;

create view my_households with (security_invoker = true) as
  select h.*, m.role, m.display_name as my_display_name, m.household_role
  from households h
  join memberships m on m.household_id = h.id
  where m.user_id = auth.uid();

grant select on my_households to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260606140000_v8_drop_legacy_baseline_provenance.sql
-- ─────────────────────────────────────────────────────────────────────
-- v8.1.2 cleanup — drop the dead households.baseline_provenance column.
--
-- An early draft of the v8 onboarding migration stored record provenance as a
-- jsonb map on households.baseline_provenance. The shipped design instead uses
-- normalized confidence/source/estimated_at/confirmed_at columns on each
-- baseline-derived entity table (transactions/budgets/goals/debts/assets), so
-- baseline_provenance was never read or written by app code — pure legacy residue.
--
-- my_households (select h.*) depends on the column, so drop + recreate the view
-- around the column drop. households.onboarding (the live per-household state
-- machine record) stays.

BEGIN;

drop view if exists my_households;

alter table households drop column if exists baseline_provenance;

create view my_households with (security_invoker = true) as
  select h.*, m.role, m.display_name as my_display_name, m.household_role
  from households h
  join memberships m on m.household_id = h.id
  where m.user_id = auth.uid();

grant select on my_households to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260607120000_v8_money_model_account_opening_balance.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money-Model Epic 1 (B1.2) — opening balance + provenance on accounts.
--
-- Additive only; safe to apply ahead of the feature flag (no behaviour change
-- until FEATURES.moneyModel.openingBalance is on). Current balance is derived in
-- the app as opening_balance + credits − debits. Provenance reuses the v8 pattern:
-- existing accounts are real data → default 'confirmed' / 'user' (never re-tagged
-- as estimate); onboarding-seeded accounts set 'estimated' until reconciled (B1.3).

BEGIN;

alter table accounts
  add column if not exists opening_balance numeric not null default 0,
  add column if not exists confidence  text not null default 'confirmed',
  add column if not exists source      text not null default 'user',
  add column if not exists estimated_at timestamptz,
  add column if not exists confirmed_at timestamptz;

alter table accounts drop constraint if exists accounts_confidence_chk;
alter table accounts add  constraint accounts_confidence_chk
  check (confidence in ('estimated','confirming','confirmed'));
alter table accounts drop constraint if exists accounts_source_chk;
alter table accounts add  constraint accounts_source_chk
  check (source in ('onboarding','user','bank'));

comment on column accounts.opening_balance is
  'Money-Model B1.2 — opening balance; current balance = opening + credits − debits.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260607130000_v8_money_model_b16_account_backfill.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money-Model B1.6 — account backfill (A2: every transaction has a funding source).
--
-- Idempotent and amount-invariant (only sets the funding source, never amounts;
-- global net unchanged). Verified via a read-only dry-run (R2) before apply:
--   orphans_after = 0, txns_repaired = 1, cash_accounts created = 2,
--   global_net 193592.90 before == after.
--
-- In-model representation: the app keys account membership off the encoded
-- `extras.paymentMethod` string ('cash' / 'asset:<id>' / 'debt:<id>' / legacy
-- key), which lib/accountBalance.ts reads. Full uuid-FK normalization of
-- transactions.account_id is a separate Money-Map-completion task, intentionally
-- not done here. `is_default` is set only when no default exists for the
-- (household, currency) pair, respecting the accounts_default_per_currency index.

BEGIN;

-- 1) System Cash account per household with transactions but no cash account.
insert into accounts (household_id, kind, name, currency, is_default, opening_balance, confidence, source)
select
  h.id, 'cash', 'Cash', coalesce(h.base_currency,'USD'),
  not exists (
    select 1 from accounts a2
    where a2.household_id = h.id
      and a2.currency = coalesce(h.base_currency,'USD')
      and a2.is_default and a2.deleted_at is null
  ),
  0, 'confirmed', 'user'
from households h
where exists (select 1 from transactions t where t.household_id = h.id and t.deleted_at is null)
  and not exists (select 1 from accounts a where a.household_id = h.id and a.kind = 'cash' and a.deleted_at is null);

-- 2) Repair accountless transactions → the system Cash funding source.
update transactions
set extras = jsonb_set(coalesce(extras, '{}'::jsonb), '{paymentMethod}', '"cash"', true)
where deleted_at is null
  and (extras->>'paymentMethod') is null;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260607140000_v8_budgets_allocations.sql
-- ─────────────────────────────────────────────────────────────────────
-- Money-Model B2.3 — category sub-limits (allocations) that roll up to a budget.
-- Additive jsonb; safe ahead of the flag (no behaviour until budgetsV2.allocations
-- is on). Shape: [{ "category": "<label>", "limit": <number> }, ...]. Existing
-- budgets default to [] and are unaffected.

BEGIN;

alter table budgets
  add column if not exists allocations jsonb not null default '[]'::jsonb;

alter table budgets drop constraint if exists budgets_allocations_is_array;
alter table budgets add  constraint budgets_allocations_is_array
  check (jsonb_typeof(allocations) = 'array');

comment on column budgets.allocations is
  'Money-Model B2.3 — category sub-limits rolling up to monthly_limit.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260607150000_v8_drop_budget_allocations.sql
-- ─────────────────────────────────────────────────────────────────────
-- Decision (c) — sub-category budget allocations were removed in favour of a
-- monthly/annual → category roll-up VIEW (computed client-side via budgetRollup).
-- Drop the now-unused jsonb column added by 20260607140000_v8_budgets_allocations.sql.
-- No app code references budgets.allocations after this release.

alter table budgets drop column if exists allocations;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260607160000_v89_recurring_schedules.sql
-- ─────────────────────────────────────────────────────────────────────
-- Userback #7830371 — recurring schedules should be household + user specific
-- (they were browser-local only via localStorage). New cloud table, household-
-- scoped via RLS, with user attribution (created_by = auth.uid()). Mirrors the
-- accounts table shape (RLS via is_member/role_in, updated_at trigger, delta-sync
-- index). The app keys this as the 'recurring' entity (tableName → this table).

BEGIN;

create table if not exists recurring_schedules (
  id                 uuid primary key default gen_random_uuid(),
  household_id       uuid not null references households(id) on delete cascade,
  created_by         uuid default auth.uid(),
  txn_template       jsonb not null default '{}'::jsonb,
  frequency          text not null check (frequency in ('weekly','monthly','yearly','custom_day')),
  day_of_month       int,
  weekday            int,
  start_date         date not null,
  next_due_date      date not null,
  last_generated     date,
  auto_confirm       boolean not null default false,
  active             boolean not null default true,
  reminder_lead_days int,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  deleted_at         timestamptz
);

create index if not exists recurring_household
  on recurring_schedules (household_id) where deleted_at is null;
create index if not exists recurring_updated_idx
  on recurring_schedules (household_id, updated_at);

alter table recurring_schedules enable row level security;

drop policy if exists "recurring_read"   on recurring_schedules;
drop policy if exists "recurring_insert" on recurring_schedules;
drop policy if exists "recurring_update" on recurring_schedules;
drop policy if exists "recurring_delete" on recurring_schedules;

create policy "recurring_read" on recurring_schedules for select to authenticated
  using (is_member(household_id) or is_admin('roles'));
create policy "recurring_insert" on recurring_schedules for insert to authenticated
  with check (role_in(household_id) in ('owner','admin','member'));
create policy "recurring_update" on recurring_schedules for update to authenticated
  using (role_in(household_id) in ('owner','admin','member'))
  with check (role_in(household_id) in ('owner','admin','member'));
create policy "recurring_delete" on recurring_schedules for delete to authenticated
  using (role_in(household_id) in ('owner','admin','member'));

create or replace function set_updated_at_recurring()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_recurring_updated_at on recurring_schedules;
create trigger trg_recurring_updated_at
  before update on recurring_schedules
  for each row execute function set_updated_at_recurring();

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260608120000_v9_txn_redesign.sql
-- ─────────────────────────────────────────────────────────────────────
-- v9 — Transaction Forms & Categories Rebuild (vyact-txn-redesign-architect-spec_1).
--
-- Forward-only, data-first, constraints LAST (§5). Applied to prod 2026-06-08 with:
--   • M0 restore point: _backup_v9_{transactions,accounts,budgets} tables (in-DB;
--     PITR not triggerable via MCP — capture a dashboard backup before re-running
--     elsewhere).
--   • INV-9 verified: spend 91,390.10 and income 301,232.00 identical before/after;
--     40 rows preserved; 0 violations; 3 unresolvable cases logged to
--     migration_issues (legacy paymentMethod keys → system Cash; transfer
--     destination best-effort) — never dropped.
--
-- Key decisions implemented (spec §0):
--   D1: transfers are ONE row (type='transfer', both FKs, category NULL).
--   D2: reconciliation / investment value = accounts.reconciliation_offset (+ log),
--       NEVER a transactions row. Legacy balance_adjustment rows are folded into
--       the offset and deleted.
--   §2.4 account matrix: expense(account_id only) · income(to_account_id only) ·
--       transfer/investment(both).
--   §3: type-scoped category enums; renames keep spend/income sums identical.
--   Deviation (documented): extras functional keys (time/excluded/split/
--       paymentMethod/accountSplits) are RETAINED — §4.2 itself requires the
--       Private toggle (extras.excluded); only the forbidden linkage keys
--       (__tg / linkedToAssetId / linkedAssetId) are scrubbed.

BEGIN;

create table if not exists migration_issues (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  step text not null,
  ref_id uuid,
  detail text
);

-- M2 — accounts: strict kind enum + reconciliation fields (D2)
alter table accounts drop constraint if exists accounts_kind_check;
update accounts set kind = 'bank' where kind in ('checking','savings','wallet','other');

alter table accounts
  add column if not exists reconciliation_offset numeric not null default 0,
  add column if not exists reconciliation_log jsonb not null default '[]'::jsonb;

comment on column accounts.reconciliation_offset is
  'D2 forgiveness term: drift between computed and stated balance. Feeds net worth; NEVER spend/income.';
comment on column accounts.reconciliation_log is
  'Dated audit trail [{at, delta, kind: bank|investment, stated_value}] — account history only.';

alter table transactions alter column category drop not null;

-- FK backfill from the encoded extras.paymentMethod scheme
create or replace function _v9_resolve_account(hh uuid, pm text) returns uuid language sql stable as $$
  select case
    when pm is null or pm = '' or pm = 'cash' then
      (select id from accounts a where a.household_id = hh and a.kind = 'cash' and a.deleted_at is null limit 1)
    when pm like 'asset:%' or pm like 'debt:%' then
      coalesce(
        (select id from accounts a where a.household_id = hh and a.asset_id::text = split_part(pm, ':', 2) and a.deleted_at is null limit 1),
        (select id from accounts a where a.household_id = hh and a.kind = 'cash' and a.deleted_at is null limit 1))
    else
      (select id from accounts a where a.household_id = hh and a.kind = 'cash' and a.deleted_at is null limit 1)
  end
$$;

insert into migration_issues (step, ref_id, detail)
select 'fk_backfill_legacy_pm', t.id, 'legacy paymentMethod "'||(t.extras->>'paymentMethod')||'" mapped to system Cash'
from transactions t
where t.extras->>'paymentMethod' is not null
  and t.extras->>'paymentMethod' not in ('cash')
  and t.extras->>'paymentMethod' not like 'asset:%'
  and t.extras->>'paymentMethod' not like 'debt:%'
  and not exists (select 1 from migration_issues mi where mi.step='fk_backfill_legacy_pm' and mi.ref_id = t.id);

update transactions t set
  account_id = coalesce(t.account_id, _v9_resolve_account(t.household_id, t.extras->>'paymentMethod')),
  to_account_id = null
where t.type = 'expense' and t.account_id is null;

update transactions t set
  to_account_id = coalesce(t.to_account_id, t.account_id, _v9_resolve_account(t.household_id, t.extras->>'paymentMethod')),
  account_id = null
where t.type = 'income' and t.to_account_id is null;
update transactions set account_id = null where type = 'income' and account_id is not null;

-- M1 — single-row transfers
insert into migration_issues (step, ref_id, detail)
select 'transfer_missing_to', id, 'transfer had no destination; assigned system Cash best-effort'
from transactions t
where t.type='transfer' and t.to_account_id is null
  and not exists (select 1 from migration_issues mi where mi.step='transfer_missing_to' and mi.ref_id=t.id);

update transactions t set
  category = null,
  account_id = coalesce(t.account_id, _v9_resolve_account(t.household_id, t.extras->>'paymentMethod')),
  to_account_id = coalesce(t.to_account_id,
    nullif(_v9_resolve_account(t.household_id, t.extras->>'linkedToAssetId'), t.account_id),
    (select id from accounts a where a.household_id=t.household_id and a.kind='cash' and a.deleted_at is null limit 1))
where t.type = 'transfer';

update transactions t set to_account_id =
  coalesce((select id from accounts a where a.household_id=t.household_id and a.id <> t.account_id and a.deleted_at is null limit 1), t.to_account_id)
where t.type='transfer' and t.account_id = t.to_account_id;

-- M3..M6 — category remaps (pure renames; sums unchanged)
update transactions set category='food_dining'      where category='food';
update transactions set category='rent_mortgage'    where category='rent';
update transactions set category='other_expense'    where category='other_exp';
update transactions set category='gift_bonus'       where category='gift';
update transactions set category='rental_income'    where category='rental';
update transactions set category='business_revenue' where category='business';
update transactions set category='other_income'     where category='other_inc';
update transactions set category='other_income'     where category='investment' and type='income';
update transactions set category='loan_emi'         where category in ('debt_payment','debt_interest');
update transactions set category='other_expense'    where category like 'goal_%' or category like 'tax_%';
update transactions set type='transfer', category=null where category='debt_principal';

update budgets set category='food_dining'   where category='food';
update budgets set category='rent_mortgage' where category='rent';
update budgets set category='other_expense' where category='other_exp';

update recurring_schedules set txn_template = jsonb_set(txn_template, '{category}',
  to_jsonb(case txn_template->>'category'
    when 'food' then 'food_dining' when 'rent' then 'rent_mortgage'
    when 'other_exp' then 'other_expense' when 'gift' then 'gift_bonus'
    when 'rental' then 'rental_income' when 'business' then 'business_revenue'
    when 'other_inc' then 'other_income' else txn_template->>'category' end))
where txn_template ? 'category';

-- M2b — legacy balance_adjustment rows → reconciliation_offset (D2)
do $$
declare r record;
begin
  for r in select * from transactions where category='balance_adjustment' loop
    update accounts set
      reconciliation_offset = reconciliation_offset + (case when r.type='income' then r.amount else -r.amount end),
      reconciliation_log = reconciliation_log || jsonb_build_object('at', r.created_at, 'delta',
        (case when r.type='income' then r.amount else -r.amount end), 'kind', 'bank', 'stated_value', null)
    where id = coalesce(r.account_id, r.to_account_id);
    delete from transactions where id = r.id;
  end loop;
end $$;

-- M7 — scrub forbidden linkage keys
update transactions set extras = (extras - '__tg' - 'linkedToAssetId' - 'linkedAssetId')
where extras ?| array['__tg','linkedToAssetId','linkedAssetId'];

-- M8 — constraints LAST
alter table transactions drop constraint if exists CK_txn_type;
alter table transactions add constraint CK_txn_type
  check (type in ('expense','income','investment','transfer'));

alter table transactions drop constraint if exists CK_txn_category_by_type;
alter table transactions add constraint CK_txn_category_by_type
  check ((type in ('expense','income') and category is not null)
      or (type in ('investment','transfer') and category is null));

alter table transactions drop constraint if exists CK_txn_accounts_by_type;
alter table transactions add constraint CK_txn_accounts_by_type
  check ((type='expense'    and account_id is not null and to_account_id is null)
      or (type='income'     and account_id is null     and to_account_id is not null)
      or (type='transfer'   and account_id is not null and to_account_id is not null)
      or (type='investment' and account_id is not null and to_account_id is not null));

alter table accounts drop constraint if exists CK_account_kind;
alter table accounts add constraint CK_account_kind
  check (kind in ('cash','bank','credit_card','investment','loan'));

drop function if exists _v9_resolve_account(uuid, text);

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260612120000_v91_budgets_recurring_receivables_deeplink.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Vyact v9.1 — feedback batch (companion: vyact-v9-feedback-triage-and-solutions.md)
--   §4  budgets: strict identity (scope + year + month) + budget_allocations child table
--   §5  recurring_schedules: rrule + owner_member_id
--   §6  debts.direction/counterparty_name already existed (v7.2.0) — no DDL here
--   §7  scrub transactions.extras.accountSplits (people-split untouched)
--   §8  transactions.recurring_schedule_id + debt_id (deep-link FKs)
--
-- Forward-only. Applied to prod 2026-06-12 (4 budgets → 2 month containers + 4
-- allocations; 0 recurring; 0 accountSplits; 0 receivables).
--
-- ⚠ LESSON: the Supabase apply_migration runner autocommits per-statement, so a
--   DO-block that fails mid-way leaves earlier statements committed. The legacy
--   collapse below is therefore GUARDED to run only when no allocations exist yet
--   (re-runnable on a clean clone; a no-op once migrated). Identity constraints
--   are added LAST, after the data is clean (v9 migration discipline).
-- ============================================================================

create table if not exists migration_issues (
  id bigserial primary key, at timestamptz default now(), area text, detail text, payload jsonb
);

-- 1. budgets — strict identity columns; category becomes optional (container has none)
alter table budgets add column if not exists scope text;
alter table budgets add column if not exists period_year int;
alter table budgets add column if not exists period_month int;
alter table budgets add column if not exists custom_name text;
alter table budgets alter column category drop not null;

-- 2. budget_allocations — reintroduced as a cloud-synced CHILD TABLE (not jsonb)
create table if not exists budget_allocations (
  id uuid primary key default gen_random_uuid(),
  budget_id uuid not null references budgets(id) on delete cascade,
  household_id uuid not null references households(id) on delete cascade,
  category text not null,
  amount numeric(15,2) not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index if not exists idx_balloc_budget on budget_allocations(budget_id) where deleted_at is null;
create index if not exists idx_balloc_household on budget_allocations(household_id) where deleted_at is null;
alter table budget_allocations enable row level security;
drop policy if exists balloc_read on budget_allocations;
create policy balloc_read on budget_allocations for select using (is_member(household_id) or is_admin('roles'));
drop policy if exists balloc_insert on budget_allocations;
create policy balloc_insert on budget_allocations for insert with check (role_in(household_id) = any (array['owner','admin','member']));
drop policy if exists balloc_update on budget_allocations;
create policy balloc_update on budget_allocations for update using (role_in(household_id) = any (array['owner','admin','member']));
drop policy if exists balloc_delete on budget_allocations;
create policy balloc_delete on budget_allocations for delete using (role_in(household_id) = any (array['owner','admin','member']));
drop trigger if exists touch_budget_allocations on budget_allocations;
create trigger touch_budget_allocations before update on budget_allocations for each row execute function set_updated_at();

-- 3. collapse legacy per-category budgets → one current-month container + allocations
--    GUARDED: only when no allocations exist (autocommit-safe; no-op once migrated)
do $$
declare h record; container uuid; cy int := extract(year from now())::int; cm int := extract(month from now())::int;
begin
  if exists (select 1 from budget_allocations) then return; end if;
  for h in select distinct household_id from budgets where deleted_at is null loop
    select id into container from budgets
      where household_id=h.household_id and deleted_at is null
      order by created_at asc nulls last, id asc limit 1;
    insert into budget_allocations (budget_id, household_id, category, amount)
      select container, household_id, category, coalesce(monthly_limit,0)
        from budgets where household_id=h.household_id and deleted_at is null and category is not null;
    update budgets set scope='month',
      period_year=coalesce(extract(year from period_start)::int, cy),
      period_month=coalesce(extract(month from period_start)::int, cm),
      period_start=coalesce(period_start, make_date(cy,cm,1)),
      period_end=coalesce(period_end, (make_date(cy,cm,1)+interval '1 month - 1 day')::date),
      monthly_limit=(select coalesce(sum(monthly_limit),0) from budgets where household_id=h.household_id and deleted_at is null),
      category=null
      where id=container;
    update budgets set deleted_at=now()
      where household_id=h.household_id and deleted_at is null and id<>container;
  end loop;
end $$;
update budgets set scope='month',
  period_year=coalesce(period_year, extract(year from now())::int),
  period_month=coalesce(period_month, extract(month from now())::int),
  period_start=coalesce(period_start, date_trunc('month',now())::date),
  period_end=coalesce(period_end, (date_trunc('month',now())+interval '1 month - 1 day')::date)
  where deleted_at is null and scope is null;

-- 4. recurring_schedules — RRULE + owner (§5)
alter table recurring_schedules add column if not exists rrule text;
alter table recurring_schedules add column if not exists owner_member_id uuid;

-- 5. transactions — deep-link FKs (§5 materialisation, §8 debt drill)
alter table transactions add column if not exists recurring_schedule_id uuid references recurring_schedules(id) on delete set null;
alter table transactions add column if not exists debt_id uuid references debts(id) on delete set null;
create index if not exists idx_txn_recurring on transactions(recurring_schedule_id) where recurring_schedule_id is not null;
create index if not exists idx_txn_debt on transactions(debt_id) where debt_id is not null;

-- 6. §7 — scrub account-split (people-split untouched)
update transactions set extras = extras - 'accountSplits' where extras ? 'accountSplits';

-- 7. CONSTRAINTS LAST — strict budget identity (§4.1)
create unique index if not exists uq_budget_month on budgets(household_id, period_year, period_month) where scope='month' and deleted_at is null;
create unique index if not exists uq_budget_annual on budgets(household_id, period_year) where scope='annual' and deleted_at is null;

-- 8. assertion
do $$ begin
  if exists (select 1 from transactions where extras ? 'accountSplits') then raise exception 'accountSplits scrub incomplete'; end if;
end $$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260612120100_v91_feedback_batch.sql
-- ─────────────────────────────────────────────────────────────────────
-- Vyact v9.1 — feedback batch schema (triage doc §4/§5/§6/§7/§8).
--
-- Covers: budget strict identity + allocations child table (§4, fixes Inv A
-- parallel-budget minting), recurring RRULE + owner + single-source-of-truth FK
-- (§5), debt receivables already had columns (§6 is UI-only), transactions.debt_id
-- for the §8 debt drill-down, and the forward-only accountSplits scrub (§7).
--
-- DISCIPLINE (v9 txn-redesign rules):
--   • forward-only, idempotent (safe to re-run).
--   • additive columns/tables first; the DESTRUCTIVE accountSplits scrub is the
--     LAST section and is gated — run it only after the §7 UI no longer writes
--     accountSplits, with an INV-9-style before/after balance reconcile.
--   • never drop data silently — multi-account rows are logged to migration_issues.
--   • APPLY ONLY after the v9.1 feature waves land and a dry-run reconciles totals.
--     This file is the tracked source of truth; it is NOT auto-applied.

-- ── scratch: issues log (idempotent) ────────────────────────────────────────
create table if not exists migration_issues (
  id bigint generated always as identity primary key,
  migration text not null,
  kind text not null,
  entity_id text,
  detail jsonb,
  logged_at timestamptz not null default now()
);

-- ── §4 — budgets: strict (scope, year, month) identity ──────────────────────
alter table budgets add column if not exists scope        text;
alter table budgets add column if not exists period_year  int;
alter table budgets add column if not exists period_month int;
alter table budgets add column if not exists custom_name  text;

-- Backfill scope + period_year/month from the legacy period + period_start.
update budgets set scope = case
    when period = 'annual'                       then 'annual'
    when period = 'custom'                       then 'custom'
    else 'month'                                  -- 'monthly'/null/others → month
  end
  where scope is null;

update budgets set
    period_year  = nullif(extract(year  from period_start)::int, 0),
    period_month = case when scope = 'month' then extract(month from period_start)::int else null end
  where period_start is not null and period_year is null;

-- Resolve period_start/period_end for month & annual where missing (TD-13 cols).
update budgets set
    period_start = make_date(period_year, period_month, 1),
    period_end   = (make_date(period_year, period_month, 1) + interval '1 month - 1 day')::date
  where scope = 'month' and period_year is not null and period_month is not null and period_start is null;
update budgets set
    period_start = make_date(period_year, 1, 1),
    period_end   = make_date(period_year, 12, 31)
  where scope = 'annual' and period_year is not null and period_start is null;

-- Identity: one budget per (household, scope, year[, month]). Partial unique
-- indexes — custom budgets are id-identified and excluded. This is what makes a
-- budget the SAME budget on every device (Investigation A root-cause fix).
-- NOTE: if duplicates exist pre-migration, this index creation will fail; the
-- gated runbook de-dupes into migration_issues first (see §pre-checks below).
create unique index if not exists uq_budget_month
  on budgets (household_id, period_year, period_month)
  where scope = 'month' and deleted_at is null;
create unique index if not exists uq_budget_annual
  on budgets (household_id, period_year)
  where scope = 'annual' and deleted_at is null;

-- ── §4 — budget_allocations child table (the reintroduced allocations, done
--    right: a row-synced, RLS'd child table, NOT the dropped v8.7 jsonb) ──────
create table if not exists budget_allocations (
  id uuid primary key default gen_random_uuid(),
  budget_id uuid not null references budgets(id) on delete cascade,
  household_id uuid not null references households(id) on delete cascade,
  category text not null,
  amount numeric(15,2) not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index if not exists ix_balloc_budget on budget_allocations (budget_id) where deleted_at is null;
create unique index if not exists uq_balloc_cat on budget_allocations (budget_id, category) where deleted_at is null;

alter table budget_allocations enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where tablename = 'budget_allocations' and policyname = 'balloc_household') then
    create policy balloc_household on budget_allocations
      using (household_id in (select household_id from memberships where user_id = auth.uid()))
      with check (household_id in (select household_id from memberships where user_id = auth.uid()));
  end if;
end $$;

-- ── §5 — recurring schedules: RRULE + owner + single-source-of-truth ────────
alter table recurring_schedules add column if not exists rrule           text;
alter table recurring_schedules add column if not exists owner_member_id uuid references memberships(id) on delete set null;
alter table recurring_schedules add column if not exists auto_confirm    boolean not null default true;

-- Backfill an RRULE from the legacy frequency enum (best-effort; the form will
-- author proper RRULEs going forward).
update recurring_schedules set rrule = case frequency
    when 'weekly'     then 'FREQ=WEEKLY;INTERVAL=1'
    when 'monthly'    then 'FREQ=MONTHLY;INTERVAL=1'
    when 'yearly'     then 'FREQ=YEARLY;INTERVAL=1'
    when 'custom_day' then 'FREQ=MONTHLY;INTERVAL=1'
    else 'FREQ=MONTHLY;INTERVAL=1'
  end
  where rrule is null;

-- ── §5/§8 — transactions: link generated txns to their schedule, and txns to a
--    debt for the §8 debt drill-down ──────────────────────────────────────────
alter table transactions add column if not exists recurring_schedule_id uuid references recurring_schedules(id) on delete set null;
alter table transactions add column if not exists debt_id               uuid references debts(id) on delete set null;
create index if not exists ix_txn_schedule on transactions (recurring_schedule_id) where recurring_schedule_id is not null;
create index if not exists ix_txn_debt     on transactions (debt_id) where debt_id is not null;

-- Backfill debt_id from the v9 EMI split metadata in extras.
update transactions
  set debt_id = (extras->'emi_split'->>'debt_id')::uuid
  where debt_id is null
    and extras ? 'emi_split'
    and (extras->'emi_split'->>'debt_id') ~ '^[0-9a-f-]{36}$';

-- ════════════════════════════════════════════════════════════════════════════
